// Упражнения в тетрадь главы «Ъ и Ь». n — постоянный номер: не менять и не переиспользовать.
// Пропуск «..» — место, где нужно решить: ъ, ь или ничего. Цитаты — по корпусу tools/lit, дословно, ё восстановлена.
// Файл собран из исходников в scratchpad (генератор подставляет пропуски, подписи цитат и ключи из разметки).
const ZN2_CLASSIC=[
// ── Урок 1. Разделительный ъ
 {n:1,l:1,st:1,task:'Прочитать слова. Выписать в первый столбик слова с разделительным ъ, во второй — слова с приставкой на согласный, после которой ъ не пишется. В словах первого столбика выделить приставку и подчеркнуть букву после ъ.',
  obr:'Съёмка: приставка с-, после ъ — ё. Сэкономить: приставка с-, дальше э — ъ не нужен.',
  body:'Подъезд, сэкономить, объявление, безоблачный, съёмка, разузнать, отобрать, въехать, безаварийный, изъян, подыграть, отъезд, предъюбилейный, сузить, взъерошенный, безъядерный, отучиться, разъединить, обогреть, межъярусный.',
  key:'С ъ: под-ъ-езд, об-ъ-явление, с-ъ-ёмка, в-ъ-ехать, из-ъ-ян, от-ъ-езд, пред-ъ-юбилейный, вз-ъ-ерошенный, без-ъ-ядерный, раз-ъ-единить, меж-ъ-ярусный (после ъ — е, ё, ю, я).<br>Без ъ: сэкономить (э), безоблачный (о), разузнать (у), отобрать (о), безаварийный (а), подыграть (ы), сузить (у), отучиться (у), обогреть (о).'},
 {n:2,l:1,st:2,task:'Переписать, вставляя ъ, где он нужен. Записать сочетания в два столбика: с ъ и без ъ. Обозначить приставку.',
  obr:'С..есть кашу — съесть (с- + е); с..экономить время — сэкономить (с- + э).',
  body:'Раз..яснить правило, с..экономить время, под..ёмный кран, без..ошибочный ответ, об..единить усилия, от..обрать билеты, в..езд в город, с..ыграть в шахматы, из..ян в ткани, раз..уться у двери, пред..ставить героя, без..умный поступок, из..ять лишнее, с..едобный гриб, об..ойти лужу, под..ыскать слово, сверх..естественная сила, от..езд в лагерь, без..облачное небо, раз..ярённый бык.',
  key:'С ъ: разъяснить, подъёмный, объединить, въезд, изъян, изъять, съедобный, сверхъестественная, отъезд, разъярённый.<br>Без ъ: сэкономить, безошибочный, отобрать, сыграть, разуться, безумный, обойти, подыскать, безоблачное, представить (после приставки а, о, у, э или ы — знака нет).'},
 {n:3,l:1,st:2,task:'Образовать от данных слов новые слова с приставками, указанными в скобках. Записать, вставляя ъ, где он нужен. Объяснить, почему в одних словах ъ есть, а в других нет.',
  obr:'Есть (с-, по-): съесть — приставка на согласный перед е; поесть — приставка на гласный, знак не нужен.',
  body:'Корень -ём- (под-, при-, с-…ка, об-). Есть (с-, по-, до-, об-…ся). Яснить (раз-, по-, об-). Единить (об-, раз-, со-). Ёжиться (с-, по-). Явить (об-, из-, про-).',
  key:'Подъём, приём, съёмка, объём. Съесть, поесть, доесть, объесться. Разъяснить, пояснить, объяснить. Объединить, разъединить, соединить. Съёжиться, поёжиться. Объявить, изъявить, проявить.<br>Ъ пишется после приставок на согласный (под-, с-, об-, раз-, из-); после приставок на гласный (при-, по-, до-, со-, про-) е, ё, я и так обозначают [й\'] с гласным — знак не нужен.'},
 {n:4,l:1,st:3,task:'Сравнить слова в парах. Объяснить, почему в одном слове пары пишется ъ, а в другом нет. Два слова с ъ (на выбор) записать в транскрипции и указать, сколько в них букв и звуков.',
  obr:'Приезд — подъезд: при- кончается на гласный, под- — на согласный. Подъезд [падй\'э́ст]: 7 букв, 7 звуков.',
  body:'Приезд — подъезд; поесть — съесть; заехать — въехать; приём — подъём; проявить — объявить; поединок — объединить; поёжиться — съёжиться; сел — съел.',
  key:'Во всех парах первое слово — с приставкой на гласный (при-, по-, за-, про-) или без приставки (поединок — по- + единок; сел), второе — с приставкой на согласный (под-, с-, в-, об-) перед е, ё, я: пишется ъ.<br>Транскрипция: подъезд [падй\'э́ст] — 7 букв, 7 звуков; съел [сй\'э́л] — 4 буквы, 4 звука; подъём [падй\'о́м] — 6 букв, 6 звуков. Ъ звука не даёт, а е (ё) после него — два звука.'},
 {n:5,l:1,st:2,task:'1) Переписать сложные слова, вставляя ъ, где он нужен. Выделить первую часть слова. 2) Составить предложения с двумя словами, в которых ъ пишется, и с одним, в котором не пишется.',
  obr:'Двух..ярусная кровать — двухъярусная (двух- + я); трёх..этажный дом — трёхэтажный (трёх- + э).',
  body:'Двух..ярусная кровать, трёх..этажный дом, четырёх..угольник на доске, трёх..язычный словарь, двух..актный спектакль, четырёх..ярусный зал театра, двух..очковый бросок, трёх..ярусный торт, двух..этажный автобус, двух..ядерный процессор, трёх..оконный фасад, четырёх..этажная школа.',
  key:'1) Двухъярусная, трёхэтажный (без знака), четырёхугольник (без знака), трёхъязычный, двухактный (без знака), четырёхъярусный, двухочковый (без знака), трёхъярусный, двухэтажный (без знака), двухъядерный, трёхоконный (без знака), четырёхэтажная (без знака). Ъ — только перед я (е, ё, ю) после двух-, трёх-, четырёх-; перед а, о, у, э знака нет.<br>2) Примерно: В детской стоит двухъярусная кровать. На праздник испекли трёхъярусный торт. Мы живём в четырёхэтажном доме.'},
 {n:6,l:1,st:3,task:'Переписать, вставляя ъ, где он нужен. Обозначить приставку в словах с пропуском. Объяснить, почему в некоторых словах знак не нужен.',
  obr:'Раз..яснит — разъяснит: приставка раз- на согласный, дальше я.',
  body:'1. Под..ём на горку обледенел. 2. Утром наш автобус медленно в..ехал в горный посёлок. 3. Мы с нетерпением слушали, как учитель раз..яснит правило. 4. Сквозняк с..орвал шапку. 5. Перед дальней дорогой папа проверил, без..опасен ли путь через перевал. 6. Котёнок испугался грома, с..ёжился и спрятался под диваном. 7. В об..явлении на двери школы сообщалось, что занятия кружка переносятся на субботу. 8. Когда река разлилась, деревенские мальчишки от..ыскали брод. 9. Сосед с..экономил на обедах и купил учебник. 10. Мы спорили целый час, но в конце концов об..единили два проекта в один. 11. Об..ём ящика проверили заранее.',
  key:'1) Подъём; 2) въехал; 3) разъяснит; 4) сорвал (без знака); 5) безопасен (без знака); 6) съёжился; 7) объявлении; 8) отыскали (без знака); 9) сэкономил (без знака); 10) объединили; 11) Объём.<br>Без знака: сорвал (о), безопасен (о), отыскали (ы), сэкономил (э) — после приставки не е, ё, ю, я.'},
 {n:7,l:1,st:2,task:'Переписать, вставляя ъ, где он нужен. Выделить иноязычную приставку или первую часть пан-, транс-. Значение незнакомых слов уточнить по словарю.',
  obr:'Ад..ютант генерала — адъютант: ад- + ю.',
  body:'Ад..ютант генерала, ин..екция витаминов, об..ект на карте, транс..европейская магистраль, пан..европейский форум, контр..удар нападающих, транс..океанский перелёт, пан..американские игры, контр..атака хоккеистов, ин..екционный шприц.',
  key:'С ъ: адъютант, инъекция, объект, трансъевропейская, панъевропейский, инъекционный (перед е, ю).<br>Без ъ: контрудар, трансокеанский, панамериканские, контратака (перед у, о, а).<br>Пояснения к ответу: адъютант — помощник командира; инъекция — укол; объект — предмет, место, на которое направлено действие.'},
 {n:8,l:1,st:4,task:'Прочитать предложения писателей. Переписать, вставляя ъ, где он нужен. Обозначить приставку. Объяснить случаи, когда знак не пишется.',
  obr:'Под..ехав — подъехав: под- + е.',
  body:'1. «Да вот она», — отвечал ямщик, указывая на деревушку, и с этим словом мы в неё в..ехали. (А. С. Пушкин, «Капитанская дочка») 2. Дрожки остановились перед трёх..этажным домом, у самого под..езда, и гусар вбежал на крыльцо. (А. С. Пушкин, «Повести Белкина») 3. Изволок — отлогая гора; некрутой длинный под..ём. (С. Т. Аксаков, «Детские годы Багрова-внука») 4. Грушницкий пришёл ко мне в шесть часов вечера и об..явил, что завтра будет готов его мундир, как раз к балу. (М. Ю. Лермонтов, «Герой нашего времени») 5. Лёжа на спине, он смотрел теперь на высокое, без..облачное небо. (Л. Н. Толстой, «Анна Каренина») 6. Под..ехав к подошве Койшаурской горы, мы остановились возле духана. (М. Ю. Лермонтов, «Герой нашего времени») 7. Причиною такого неожиданного от..езда было следующее письмо. (Л. Н. Толстой, «Детство») 8. Был июль; солнце светило ярко; кругом меня развёртывался необ..ятный простор полей с дозревавшим хлебом. (Ф. М. Достоевский, «Село Степанчиково и его обитатели») 9. Я с..ёжился ещё более, горькие слёзы жгли мои щёки. (В. Г. Короленко, «Дети подземелья») Пояснения: дрожки — лёгкая открытая повозка; изволок — длинный пологий склон; духан — небольшая харчевня на Кавказе.',
  key:'1) въехали; 2) трёхэтажным (без знака), подъезда; 3) подъём; 4) объявил; 5) безоблачное (без знака); 6) Подъехав; 7) отъезда; 8) необъятный; 9) съёжился.<br>Ъ — после приставок в-, под-, об-, от-, с- перед е, ё, я (необъятный — ъ после исторической приставки об-). Без знака: трёхэтажным — после трёх- стоит э; безоблачное — после без- стоит о.'},
 {n:9,l:1,st:4,task:'Найти и исправить ошибки в употреблении ъ. Выписать исправленные слова, объяснить каждое исправление. Указать слова, написанные верно, в которых можно было ошибиться.',
  body:'Накануне отъезда в лагерь вожатый обьяснил нам правила. Утром автобус подъехал к подьезду школы. Чтобы съэкономить время, чемоданы сложили заранее. Водитель у нас опытный: за двадцать лет — ни одной аварии, недаром его наградили за безъаварийную езду. Лагерь стоит у подножия горы, и до трёхъэтажного корпуса пришлось подниматься по крутому подъёму. В первый же вечер нас собрали на предюбилейный концерт: лагерю исполнялось пятьдесят лет. Вожатые разъяснили, что концерт снимают для телевидения и съёмка займёт весь вечер. Младших ребят из соседних детъяслей тоже привели посмотреть.',
  key:'Ошибки: 1) обьяснил → объяснил (после приставки об- — только ъ, не ь); 2) подьезду → подъезду (то же); 3) съэкономить → сэкономить (перед э ъ не пишется); 4) безъаварийную → безаварийную (перед а ъ не пишется); 5) трёхъэтажного → трёхэтажного (после трёх- перед э знака нет); 6) предюбилейный → предъюбилейный (пред- + ю); 7) детъяслей → детяслей (сложносокращённое слово: детские ясли).<br>Верно: отъезда, подъехал, подъёму, разъяснили, съёмка.'},
 {n:10,l:1,st:3,task:'Распределить слова по группам: 1) ъ после приставки; 2) ъ после двух-, трёх-, четырёх-; 3) ъ после иноязычной приставки; 4) знак не нужен: после приставки не е, ё, ю, я; 5) знак не нужен: сложносокращённое слово или приставка на гласный. Вставить ъ, где нужно.',
  obr:'Раз..езд — 1-я группа (раз- + е).',
  body:'Раз..езд, трёх..ярусный, ад..ютант, с..узить, дет..ясли, на..ездник, меж..ярусный, двух..ступенчатый, ин..екция, без..ыдейный, ин..яз, вз..ерошенный, четырёх..ядерный, транс..атлантический, пред..явитель, без..отказный, при..езжий, об..ект, над..орвать, с..естной.',
  key:'1) разъезд, межъярусный, взъерошенный, предъявитель, съестной; 2) трёхъярусный, четырёхъядерный; 3) адъютант, инъекция, объект; 4) сузить, двухступенчатый, безыдейный, трансатлантический, безотказный, надорвать; 5) детясли, иняз (сложносокращённые), наездник, приезжий (приставки на гласный).'},
 {n:11,l:1,st:5,task:'Тонкость. Объяснить написание каждого слова. Указать, в каких словах правило применяется не напрямую: приставку не видно, ъ стоит не после приставки, знак не нужен, хотя часть слова кончается на согласный.',
  body:'Изъян, необъятный, объём, неотъемлемый, фельдъегерь, детясли, иняз, пол-юрты, пол-яблока, суперъяхта, суперэлита, сверхъяркий, межъязыковой, безыдейный, подытожить, контрудар.',
  key:'Изъян, необъятный, объём, неотъемлемый — ъ после исторических приставок из-, об-, от-: корня отдельно в языке нет, но приставка выделяется. Фельдъегерь — ъ не после приставки: единичное заимствованное слово, запомнить. Детясли, иняз — сложносокращённые слова: начало — кусочек другого слова (детские, иностранный), а не приставка, ъ не пишется. Пол-юрты, пол-яблока — пишутся через дефис, дефис сам разделяет части, ъ не нужен. Суперъяхта, сверхъяркий, межъязыковой — приставки супер-, сверх-, меж- на согласный перед я: ъ. Суперэлита — перед э ъ нет. Безыдейный, подытожить — после приставки и переходит в ы, знака нет. Контрудар — иноязычная приставка контр- перед у: ъ нет.'},
 {n:12,l:1,st:5,os:'диктант',task:'Объяснительный диктант. Записать текст под диктовку (или переписать, вставляя ъ, где нужно). Объяснить каждый пропуск.',
  body:'Переезд. Летом мы переезжали на другую квартиру. С утра во двор под..ехал большой грузовик. Папа раз..яснил грузчикам, какие коробки хрупкие, и они осторожно вкатили тележку в лифт. Самым тяжёлым оказался книжный шкаф: он не проходил в дверь, и его пришлось раз..обрать. Сестра боялась, что мы не успеем за один раз, но всё уместилось: машина была большого об..ёма. Младший брат устроился в уголке кабины и всю дорогу молчал. Наш корпус оказался трёх..этажным, с уютным двором и детской площадкой. Перед шлагбаумом водитель терпеливо стоял, пока его поднимут, и даже успел с..есть бутерброд. Вечером мы попробовали пирог, который испекла соседка, и раз..ошлись по комнатам. Прощание со старой квартирой было грустным, а новоселье — весёлым.',
  key:'подъехал, разъяснил, разобрать (без знака), объёма, трёхэтажным (без знака), съесть, разошлись (без знака).<br>Ъ — после приставок на согласный (под-, раз-, об-, с-) перед е, ё. Без знака: разобрать, разошлись (после приставки о), трёхэтажным (после трёх- — э).'},
 {n:13,l:1,st:4,task:'Лингвистическая задача. Ответить на вопросы письменно, приводя свои примеры (по 2–3 на каждый ответ). 1) Почему пишут «съехать», но «сыграть», «сузить»? 2) Почему «подъезд», но «приезд»? 3) Почему «трёхъярусный», но «трёхэтажный»? 4) Почему «детясли» без ъ, хотя «дет» кончается на согласный? 5) Почему после приставки никогда не пишут разделительный ь?',
  body:'Слова для справки: съехать, сыграть, сузить, подъезд, приезд, трёхъярусный, трёхэтажный, детясли, иняз, объявление, поехать, сэкономить, разъезд, разыграть, сверхъестественный, двухъядерный.',
  key:'1) Ъ пишется только перед е, ё, ю, я; в «сыграть», «сузить» после приставки стоят ы (из и) и у (съёжиться, съесть — с ъ). 2) При- кончается на гласный: после гласного е и так даёт [й\'э] (поехать, приезд); под- — на согласный: нужен ъ (подъезд, объявление, разъезд). 3) После двух-, трёх-, четырёх- ъ пишется только перед е, ё, ю, я (трёхъярусный, двухъядерный), перед э — нет (трёхэтажный). 4) Детясли, иняз — сложносокращённые слова: «дет» — кусочек слова «детские», а не приставка, правило о ъ на них не распространяется. 5) Разделительный ь пишется только внутри корня или перед окончанием; на границе приставки и корня пишется ъ: подъезд, сверхъестественный.'},
 {n:14,l:1,st:2,task:'Подобрать к каждому слову два-три однокоренных слова с приставкой и разделительным ъ. Выделить приставку. С двумя словами составить предложения.',
  obr:'Ясный — разъяснить, объяснение.',
  body:'Езда, ясный, явить, единый, ёмкость, есть (кушать), ядро (как в слове «ядерный»), юбилей, ярус.',
  key:'Примерно: езда — подъезд, съезд, объездной, разъезд; ясный — разъяснить, объяснение; явить — объявить, изъявить, предъявить; единый — объединить, разъединить; ёмкость — объём, подъём (корень ём — «брать»), съёмка; есть — съесть, объесться, съедобный; ядро — двухъядерный, безъядерный; юбилей — предъюбилейный; ярус — межъярусный, надъярусный. Предложения: Кот съёжился от холода. На двери подъезда висело объявление.'},
// ── Урок 2. Разделительный ь
 {n:15,l:2,st:1,task:'Прочитать слова. Выписать в первый столбик слова с разделительным ь, во второй — слова, где ь обозначает мягкость согласного. В словах первого столбика подчеркнуть букву после ь.',
  obr:'Вьюга — разделительный ь (после него ю); просьба — ь показывает мягкость [с\'].',
  body:'Вьюга, письмо, семья, коньки, статьи, пальто, листья, деньки, воробьи, платье, просьба, бельё, соловьиный, пьеса, тетрадь, бульон, крылья, бьёт, гвоздь, обезьяна, лось, счастье.',
  key:'Разделительный ь: вьюга (ю), семья (я), статьи (и), листья (я), воробьи (и), платье (е), бельё (ё), соловьиный (и), пьеса (е), бульон (о), крылья (я), бьёт (ё), обезьяна (я), счастье (е).<br>Ь мягкости: письмо, коньки, пальто, деньки, просьба, тетрадь, гвоздь, лось.'},
 {n:16,l:2,st:2,task:'Переписать, вставляя ъ или ь. Объяснить выбор: есть ли перед пропуском приставка на согласный.',
  obr:'В..юн — вьюн (приставки нет, ь); от..явленный — отъявленный (приставка от-).',
  body:'В..юн, об..ём, стат..я, раз..единить, друз..я, с..ёмка, плат..е, раз..яснить, бел..ё, от..явленный, гост..я, с..ел кашу, бур..ян, об..явление, коп..ё, интерв..ю, из..ян, обез..яна, в..едливый, посыпать сол..ю, из..ятие, лис..и норы.',
  key:'С ъ (после приставки на согласный): объём, разъединить, съёмка, разъяснить, отъявленный, съел, объявление, изъян, въедливый, изъятие.<br>С ь (внутри слова, приставки нет): вьюн, статья, друзья, платье, бельё, гостья, бурьян, копьё, интервью, обезьяна, солью, лисьи.'},
 {n:17,l:2,st:2,task:'Образовать от слов форму «много» (или «их несколько») и записать. Подчеркнуть разделительный ь. Указать, в каких словах ь стоит перед и.',
  obr:'Брат — братья; ручей — ручьи (ь перед и).',
  body:'Брат, лист (на дереве), перо, крыло, колос, стул, друг, зять, дерево, князь, звено, ком, ручей, соловей, воробей, муравей, улей, кол (заострённая палка).',
  key:'Братья, листья, перья, крылья, колосья, стулья, друзья, зятья, деревья, князья, звенья, комья, колья; ручьи, соловьи, воробьи, муравьи, ульи — ь перед и.'},
 {n:18,l:2,st:3,task:'Вставить ь, где нужно. Записать пары. Объяснить, почему в одном слове пары разделительный ь есть, а в другом нет. Две пары записать в транскрипции.',
  obr:'Руч..ей — руч..и: ручей [руч\'э́й\'] — [й\'] перед э не слышится, ь нет; ручьи [руч\'й\'и́] — [й\'] слышится, ь нужен.',
  body:'Руч..ей — руч..и; солов..ей — солов..иный; вороб..ей — вороб..и; мурав..ей — мурав..иный; ул..ей — ул..и; лис..ий хвост — лис..я нора; птич..ий голос — птич..и голоса; волч..ий след — волч..я стая; сем..я (у растения) — сем..я (родные).',
  key:'Ручей — ручьи; соловей — соловьиный; воробей — воробьи; муравей — муравьиный; улей — ульи; лисий — лисья; птичий — птичьи; волчий — волчья; семя — семья.<br>В первом слове пары после согласного звучит гласный без [й\'] (ручей [руч\'э́й\'], лисий [л\'и́с\'ий\'], семя [с\'э́м\'а]) — ь не нужен; во втором слышится [й\'] перед гласным (ручьи [руч\'й\'и́], лисья [л\'и́с\'й\'а], семья [с\'им\'й\'а́]) — пишется разделительный ь.'},
 {n:19,l:2,st:2,task:'Вставить ь или й. Сформулировать, когда в словах из других языков пишется ьо, а когда йо.',
  obr:'Бул..он — ьо после согласного л; ра..он — йо после гласного а.',
  body:'Бул..он, ра..он, павил..он, ма..ор, почтал..он, медал..он, ма..онез, батал..он, шампин..он, ко..от, компан..он, гил..отина, ..огурт, кан..он, Нью-..орк.',
  key:'Бульон, район, павильон, майор, почтальон, медальон, майонез, батальон, шампиньон, койот, компаньон, гильотина, йогурт, каньон, Нью-Йорк.<br>Вывод: после согласного — ьо (бульон, павильон), после гласного и в начале слова — йо (район, майор, йогурт).'},
 {n:20,l:2,st:3,task:'Переписать, вставляя ъ или ь. Подчеркнуть слова, где знак показывает границу приставки и корня.',
  obr:'По обочине тянулся густой бур..ян — бурьян (ь в корне).',
  body:'1. Бур..ян разросся за лето так, что у сарая не видно стало высокого крыльца и под..ёма к двери. 2. Над прудом с криком носились вороб..и. 3. Сосед в..едливо расспрашивал нас о каникулах. 4. После уроков мы с друз..ями пошли в парк. 5. В зоопарке юркая обез..яна весь день прыгала по веткам и смешила посетителей. 6. Под тяжёлым снегом гнулись сосновые суч..я. 7. Учитель раз..яснил, как составить план. 8. Портниха сшила девочке нарядное плат..е к празднику. 9. Ч..и это следы на песке? 10. Ведущий взял интерв..ю у капитана команды, которая впервые выиграла кубок города. 11. К лету из города вернулись сыновь..я.',
  key:'1) Бурьян, подъёма; 2) воробьи; 3) въедливо; 4) друзьями; 5) обезьяна; 6) сучья; 7) разъяснил; 8) платье; 9) Чьи; 10) интервью; 11) сыновья.<br>Граница приставки и корня — подъёма, въедливо, разъяснил (ъ); в остальных словах разделительный ь внутри слова.'},
 {n:21,l:2,st:3,task:'Прочитать предложения писателей. Переписать, вставляя ь, где нужно. Подчеркнуть букву после разделительного ь. Объяснить, почему в одном слове знака нет.',
  obr:'Руч..и — ручьи: ь внутри слова перед и.',
  body:'1. Дороги были непроходимы, люди вязли в бездонной грязи; реки разливались на несколько вёрст; руч..и становились реками. (А. С. Пушкин, «История Пугачёва») 2. Ночь уж ложилась на горы, и туман начинал бродить по ущел..ям. (М. Ю. Лермонтов, «Герой нашего времени») 3. Лучи сквозили, трепетали тени; / Не умолкал в дерев..ях птич..ий гам; / Мелькали в чаще быстрые олени, / И ловчий рог взывал по временам. (Ф. И. Тютчев) 4. Лист..я чуть шумели над моей головой; по одному их шуму можно было узнать, какое тогда стояло время года. (И. С. Тургенев, «Записки охотника») 5. Около дерев..ев в цвету вились и жужжали целые рои пчёл, ос и шмелей. (С. Т. Аксаков, «Детские годы Багрова-внука») 6. И тут только поверил я словам тётушки, что солов..и не давали ей спать. (С. Т. Аксаков, «Детские годы Багрова-внука») 7. С этой стороны ущел..е шире и превращается в зелёную лощину; по ней в..ётся пыльная дорога. (М. Ю. Лермонтов, «Герой нашего времени») 8. Мы шли обочиной дороги, сплошь покрытой бурыми прошлогодними лист..ями, ещё не высохшими после снега. (А. И. Куприн, «Олеся») 9. И вот ещё запах: в саду — костёр, и крепко тянет душистым дымом вишнёвых суч..ев. (И. А. Бунин, «Антоновские яблоки») Пояснения: ловчий рог — охотничий рог; лощина — неглубокая долина.',
  key:'1) ручьи; 2) ущельям; 3) деревьях, птичий (без знака); 4) Листья; 5) деревьев; 6) соловьи; 7) ущелье, вьётся; 8) листьями; 9) сучьев.<br>Птичий — без ь: после ч звучит [и] без [й\'] (сравнить: птичьи голоса).'},
 {n:22,l:2,st:4,task:'Найти и исправить ошибки в употреблении ъ и ь. Объяснить каждое исправление. Выписать верно написанные слова с разделительными знаками.',
  body:'Наша семя каждое лето ездит к тёте. У её подьезда на верёвке сушатся платъя, а за забором начинается пустырь, заросший бурьяном. По утрам тётя варит куриный бульён и стряпает пироги с шампиньонами. Однажды мы с братом увидели в роще целую муравьиную дорожку: муравъи несли по ней хвоинки и сухие листъя. Вечером к нам в гости приходят тётины друзъя, и мы все вместе обьедаемся пирогами. Счастье — это когда все вместе!',
  key:'Ошибки: 1) семя → семья (разделительный ь: [й\'] перед а; «семя» — другое слово); 2) подьезда → подъезда (после приставки под- — ъ); 3) платъя → платья (внутри слова — ь); 4) бульён → бульон (в заимствованном слове после согласного — ьо); 5) муравъи → муравьи; 6) листъя → листья; 7) друзъя → друзья; 8) обьедаемся → объедаемся (приставка об-).<br>Верно: бурьяном, шампиньонами, муравьиную, счастье.'},
 {n:23,l:2,st:3,task:'Распределить слова по группам: 1) ъ после приставки; 2) ь перед е, ё, ю, я; 3) ь перед и; 4) ь перед о (в словах из других языков). Вставить знак.',
  obr:'Крупной сол..ю — 2-я группа.',
  body:'Крупной сол..ю, под..ём, мурав..и, павил..он, в..езд, ущел..е, ул..и, почтал..он, раз..ехаться, бур..ян, острые кол..я, из..ять, сов..и глаза, медал..он, вз..ерошить, п..ёт, лис..и норы, компан..он, с..ёмщик, руж..ё.',
  key:'1) подъём, въезд, разъехаться, изъять, взъерошить, съёмщик; 2) солью, ущелье, бурьян, колья, пьёт, ружьё; 3) муравьи, ульи, совьи, лисьи; 4) павильон, почтальон, медальон, компаньон.'},
 {n:24,l:2,st:4,task:'Сравнить пары слов. Объяснить, почему в одном слове пары пишется ъ, а в другом ь, хотя после знака одна и та же буква. Для этого найти приставку (если она есть) и доказать это подбором слов с другой приставкой.',
  obr:'Объём — бьём: объём — подъём — съём, об- — приставка, значит ъ; в «бьём» приставки нет (от «бить») — ь.',
  body:'Въезд — вьюн; объём — бьём; съёмка — шьём; подъём — копьё; разъезд — друзья; изъян — обезьяна; отъехать — платье; съел — семья; объявление — интервью; предъюбилейный — вьюн.',
  key:'Въезд (выезд, проезд — в- приставка) — вьюн (приставки нет: ь в корне). Объём (подъём, съём — об- приставка) — бьём (от «бить», б — часть корня). Съёмка (подъём, приём — с- приставка) — шьём (от «шить»). Подъём (под- приставка) — копьё (ь перед окончанием: копья, копью). Разъезд (выезд — раз- приставка) — друзья (ь перед окончанием). Изъян (из- историческая приставка) — обезьяна (ь в корне). Отъехать (приехать — от- приставка) — платье (платья, платью). Съел (поел — с- приставка) — семья (семьи, семью). Объявление (заявление — об- приставка) — интервью (заимствованное слово, ь в корне). Предъюбилейный (пред- + юбилей) — вьюн (в — часть корня).'},
 {n:25,l:2,st:5,task:'Тонкость. Объяснить написание каждого слова. В каких словах правило о разделительных знаках действует не так, как обычно?',
  body:'Подьячий, адъютант, интервью, премьера, портьера, гильотина, каньон, район, майор, сеньор, пьедестал, фельдъегерь, объект, панъевропейский, конъюнктура.',
  key:'Подьячий — ь, а не ъ: слово образовано от «дьяк», ь принадлежит корню, «под-» здесь стоит перед корнем дьяк. Адъютант, объект, конъюнктура, панъевропейский — ъ после иноязычных приставок (ад-, об-, кон-) и части пан-. Фельдъегерь — ъ не после приставки, исключительное заимствованное слово. Интервью, премьера, портьера, пьедестал — разделительный ь в корне заимствованных слов. Гильотина, каньон, сеньор — ьо после согласного в заимствованных словах. Район, майор — после гласного [й\'о] обозначается буквами йо, знак не нужен.'},
 {n:26,l:2,st:5,os:'диктант',task:'Диктант с грамматическим заданием. Записать текст (или переписать, вставляя ъ или ь). Обозначить приставку в словах с ъ. Подчеркнуть букву после разделительного ь.',
  body:'Зимний вечер. Весь день над посёлком мела в..юга, и раз..ярённый ветер гнал снег по улицам. Порывы раскачивали голые суч..я берёз и наметали сугробы у крылец. К вечеру непогода утихла. Мы с друз..ями взяли санки и отправились к горке за школой. С горы с..езжали по очереди, а самые смелые — стоя на ногах. Петя сначала боялся, но потом раз..огнался вместе со всеми и смеялся громче всех. Когда стемнело, нас позвали домой. Хозяйка налила всем наваристого бул..она, а дед достал из духовки тёплые ватрушки. За окном снова поднималась в..юга, а в комнате было тепло. Вот оно, счаст..е: сидеть всей сем..ёй за одним столом.',
  key:'вьюга, разъярённый, сучья, друзьями, съезжали, разогнался (без знака), бульона, вьюга, счастье, семьёй.<br>Ъ — после приставки с- (съезжали); без знака: разогнался (после приставки о); ь — внутри слова (вьюга, сучья, друзьями, бульона, счастье, семьёй).'},
 {n:27,l:2,st:2,task:'1) Изменить слова по образцу и записать: пить — он пьёт, они пьют. Так же: лить, бить, вить, шить. 2) Подобрать к слову «чей» формы, отвечающие на вопросы «чья? чьё? чьи? чью?», и составить с ними словосочетания. Подчеркнуть разделительный ь.',
  obr:'Пить — пьёт, пьют; чья книга.',
  body:'Пить, лить, бить, вить, шить; чей.',
  key:'1) Пить — пьёт, пьют; лить — льёт, льют; бить — бьёт, бьют; вить — вьёт, вьют; шить — шьёт, шьют. 2) Чья тетрадь, чьё пальто, чьи варежки, чью книгу (примерно). Во всех формах ь перед ё, ю, я, и — разделительный.'},
 {n:28,l:2,st:4,task:'Прочитать предложения. Вставить ъ или ь. Объяснить каждый знак: где он стоит (после приставки или внутри слова) и перед какой буквой.',
  body:'1. Писаря встали и заложили пер..я за ухо. (А. С. Пушкин, «Дубровский») 2. Он шёл не разбирая дороги; суч..я поминутно задевали и царапали его, нога его поминутно вязла в болоте, – он ничего не замечал. (А. С. Пушкин, «Дубровский») 3. С поляны коршун поднялся, / Высоко к небу он взвился; / Всё выше, дале в..ётся он — / И вот ушёл за небосклон! (Ф. И. Тютчев) 4. Ливень размыл жилище мурав..ёв; насекомые встревоженно снуют по грязи и хлопочут около своих утонувших сожителей. (А. П. Чехов, «День за городом») 5. Из такой трёпки сад выходил почти совсем обнажённым, засыпанным мокрыми лист..ями и каким-то притихшим, смирившимся. (И. А. Бунин, «Антоновские яблоки») 6. К дому с обеих сторон прилегали тёмные дерев..я старинного сада, аллея стриженых ёлок вела к под..езду. (И. С. Тургенев, «Отцы и дети») 7. Мальчик бегал взад и вперёд по той стороне руч..я, пронзительно свистал и кричал громко, с беспокойством и испугом: — Арто, иси! (А. И. Куприн, «Белый пудель») Пояснения: Арто — кличка собаки; иси — «ко мне» (команда собаке).',
  key:'1) перья; 2) сучья; 3) вьётся; 4) муравьёв; 5) листьями; 6) деревья, подъезду; 7) ручья.<br>Ъ — только в «подъезду» (приставка под-). Остальные знаки — разделительный ь внутри слова: перед я (перья, сучья, деревья, ручья), ё (вьётся, муравьёв), и в «листьями» — перед я.'},
// ── Урок 3. Ь — знак мягкости
 {n:29,l:3,st:1,task:'Выписать слова, в которых ь обозначает мягкость согласного, в два столбика: 1) ь на конце слова; 2) ь в середине слова. Подчеркнуть согласный, мягкость которого обозначает ь.',
  obr:'Конь — на конце, мягкий [н\']; редька — в середине, мягкий [д\'].',
  body:'Конь, осень, соль, просьба, тетрадь, редька, лось, коньки, морковь, тьма, рояль, деньки, гусь, борьба, пальто, восемь, свадьба, бровь, банька, ель, тоньше, мель.',
  key:'1) На конце: конь, осень, соль, тетрадь, лось, морковь, рояль, гусь, восемь, бровь, ель, мель.<br>2) В середине: просьба, редька, коньки, тьма, деньки, борьба, пальто, свадьба, банька, тоньше.'},
 {n:30,l:3,st:2,task:'Переписать, вставляя ь, где нужно. Выделить сочетания согласных, в которых ь не пишется.',
  obr:'Доч..ка — дочка (чк, без ь); пал..цы — пальцы (мягкий л перед согласным).',
  body:'Доч..ка, веч..ный, пал..цы, пон..чик, ден..ки, камен..щик, болел..щик, пис..мо, мос..тик, точ..ный, зон..тик, гон..щик, мощ..ный, пес..ня, скол..ко, свад..ба, лодоч..ка, нян..чить, мол..ба, помощ..ник, кол..цо, бан..тик, сбор..щик, ред..ка.',
  key:'С ь: пальцы, деньки, болельщик, письмо, сколько, свадьба, мольба, кольцо, редька.<br>Без ь: вечный (чн), дочка (чк), пончик, нянчить (нч), каменщик, гонщик (нщ), мостик (ст), точный, лодочка (чк), мощный, помощник (щн), песня (сн), зонтик, бантик (нт), сборщик (рщ).'},
 {n:31,l:3,st:2,task:'Прочитать пары слов. Объяснить значение каждого слова. С каждым словом составить словосочетание. Как ь меняет звучание и смысл?',
  obr:'Угол комнаты — уголь в топке: [у́гал] — [у́гал\'].',
  body:'Угол — уголь, полка — полька, банка — банька, мел — мель, был — быль, кон — конь, брат — брать, пыл — пыль, вес — весь, хор — хорь, ел — ель, шест — шесть.',
  key:'Примерно: угол комнаты — каменный уголь; книжная полка — танцевать польку; стеклянная банка — деревенская банька; белый мел — речная мель; он был дома — быль (то, что было на самом деле); первый кон игры — вороной конь; старший брат — брать книгу; пыл спора — дорожная пыль; вес груза — весь день; школьный хор — степной хорь; он ел суп — зелёная ель; длинный шест — шесть дней.<br>Ь обозначает мягкость последнего согласного и различает слова.'},
 {n:32,l:3,st:3,task:'Переписать, вставляя ь, где нужно. Объяснить: мягкий или твёрдый л перед согласным? Значение слов в скобках помогает выбрать.',
  obr:'Пал..ма — пальма: мягкий [л\'] перед м; пол..ка (для книг) — полка: [л] твёрдый.',
  body:'Пал..ма, пол..ка (для книг), пол..ка (танец), мол..чать, дол..ше, сол..нце, скол..ко, бол..шой, вол..на, пол..за, тол..ко, мел..че, вскол..зь, пол..ный, ал..бом, фил..м, бал..зам, хол..мы, мел..ком, сил..нее, жёл..тый, бел..чонок.',
  key:'С ь (мягкий л): пальма, полька, дольше, сколько, большой, польза, только, мельче, вскользь, альбом, фильм, бальзам, мельком, сильнее, бельчонок.<br>Без ь (твёрдый л): полка, молчать, солнце, волна, полный, холмы, жёлтый.'},
 {n:33,l:3,st:3,task:'Вставить ь, где нужно. Доказать написание: изменить слово или подобрать родственное так, чтобы после мягкого согласного оказался твёрдый согласный (или конец слова).',
  obr:'В пис..ме — письмо (с\' перед м твёрдым): ь сохраняется.',
  body:'В пис..ме, о прос..бе, к свад..бе, в кос..ти (рыбы), мос..тик, о суд..бе, на ред..ке, ден..ки, париться в бан..ке, гвоз..дик, о бор..бе, пес..ни, ступен..ки, бан..тики, о мол..бе.',
  key:'В письме — письмо; о просьбе — просьба; к свадьбе — свадьба; о судьбе — судьба; на редьке — редька; деньки — денька; в баньке — банька; о борьбе — борьба; ступеньки — ступенька; о мольбе — мольба: ь сохраняется.<br>Без ь: в кости (кость: перед т\' согласный смягчается сам), мостик (мост), гвоздик (гвоздь — з перед д), песни (сочетание сн без ь, как в «песня»), бантики (бант).'},
 {n:34,l:3,st:3,task:'Переписать, вставляя ь, где нужно. Обозначить сочетания, в которых ь не пишется.',
  obr:'Бол..шой пруд у реч..ки — большой (мягкий л), речки (чк).',
  body:'1. Ступен..ки скользкие. 2. Игорь долго не мог найти свои кон..ки. 3. На столе лежало пис..мо от подруги, которое пришло ещё в понедельник. 4. Вдали зазвучала пес..ня. 5. Прабабушка часто рассказывала нам о своей непростой суд..бе. 6. Камен..щики к вечеру выложили стену из красного кирпича. 7. Сестра рисует тон..ше, чем я. 8. На берегу пруда в сухой траве сидел лягушонок, и его кругом обступила стайка любопытных зверь..ков. 9. Это была просто точ..ка. 10. Скол..ко лет этому дубу?',
  key:'1) Ступеньки; 2) коньки; 3) письмо; 4) песня (без знака); 5) судьбе; 6) Каменщики (без знака); 7) тоньше; 8) зверьков (зверь — зверьков: ь сохраняется перед твёрдым к); 9) точка (без знака); 10) Сколько.<br>Без ь: песня (сн), каменщики (нщ), точка (чк).'},
 {n:35,l:3,st:3,task:'Прочитать предложения писателей. Переписать, вставляя ь, где нужно. Объяснить, почему в некоторых словах ь не пишется.',
  obr:'Тол..ко — только: мягкий [л\'] перед к.',
  body:'1. Любоч..ка любит рисовать головки; Катен..ка же рисует тол..ко цветы и бабочек. (Л. Н. Толстой, «Отрочество») 2. Наконец, легонько, с бережливостью, какую только можно себе вообразить, он приподнял два пал..ца с тем, чтобы поймать его за кон..чик. (Н. В. Гоголь, «Нос») 3. Они боролись нескол..ко минут, наконец рыжий мал..чик одолел. (А. С. Пушкин, «Дубровский») 4. В первый урок она училась стоять и ходить на задних лап..ках, что ей ужасно нравилось. (А. П. Чехов, «Каштанка») 5. Тётка раньше никогда не боялась потёмок, но теперь почему-то ей стало жут..ко и захотелось лаят.. . (А. П. Чехов, «Каштанка») 6. Тут тол..ко, оглянувшись вокруг себя, он заметил, что они ехали прекрасною рощей; миловидная берёзовая ограда тянулась у них справа и слева. (Н. В. Гоголь, «Мёртвые души») 7. Раз она пришла на урок часом ран..ше, извиняясь тем, что в сем.. часов ей нужно ехать в Малый театр. (А. П. Чехов, «Дорогие уроки») Пояснения: Тётка — кличка собаки в рассказе.',
  key:'1) Любочка (без знака), Катенька, только; 2) пальца, кончик (без знака); 3) несколько, мальчик; 4) лапках (без знака); 5) жутко (без знака), лаять; 6) только; 7) раньше, семь.<br>Без ь: Любочка (чк), кончик (нч), лапках, жутко (твёрдые п, т перед к).'},
 {n:36,l:3,st:4,task:'Найти и исправить ошибки в употреблении ь. Объяснить каждое исправление. Выписать трудные слова, написанные верно.',
  body:'Мой дядя — болелщик футбольной команды. Каждую субботу он берёт меня на стадион. Вчера наша команда играла с гостями из соседней области. Сначала гости забили два гола, и все болельщики приуныли. Но потом малчик лет пятнадцати, молодой нападающий, сравнял счёт. Его младшая сестрёнка прыгала на трибуне от радости, а рядом махала флажком чья-то дочька. Ночьной матч закончился победой! Домой мы шли пешком, по тонькому мостику через речку. Дядя сказал, что теперь он будет ходить на каждую игру, сколько бы ни стоил билет.',
  key:'Ошибки: 1) болелщик → болельщик (мягкий л перед щ: ь пишется); 2) малчик → мальчик (мягкий л перед согласным); 3) дочька → дочка (чк, ь не пишется); 4) ночьной → ночной (чн); 5) тонькому → тонкому (н твёрдый перед к: ь не нужен).<br>Верно: болельщики, речку, сколько, пятнадцати.'},
 {n:37,l:3,st:4,task:'Лингвистическая задача. Сравнить две группы слов и объяснить, почему в словах первой группы ь нет, а во второй есть. Подобрать по два своих слова в каждую группу.',
  body:'1) Каменщик, гонщик, банщик, барабанщик, сменщик, наборщик. 2) Болельщик, кровельщик, точильщик, носильщик, рассыльщик, стекольщик.',
  key:'В первой группе перед щ стоят н или р — в сочетаниях нщ, рщ ь не пишется. Во второй группе перед щ стоит мягкий л — мягкий [л\'] перед любым согласным обозначается ь (Розенталь: перед -щик- ь пишется только после л).<br>Свои слова (примерно): 1) обманщик, жестянщик, сборщик; 2) купальщик, сигнальщик.'},
 {n:38,l:3,st:5,task:'Тонкость. Объяснить, почему ь пишется или не пишется в выделенных случаях. Сгруппировать слова по причине.',
  body:'Аллея, иллюстрация, пятьдесят, пятнадцать, семьсот, семнадцать, рязанский, январский, июньский, сентябрьский, детьми, людьми, степь, кость, восьмой — восьми, свадьба — свадьбе.',
  key:'1) Между двумя мягкими л ь не пишется: аллея, иллюстрация. 2) Ь в середине слов пятьдесят, семьсот (обе части изменяются: пятидесяти), но пятнадцать, семнадцать — без ь. 3) Перед -ск- после н, р ь не пишется: рязанский, январский; исключения — июньский, сентябрьский (и октябрьский, ноябрьский, декабрьский). 4) Ь в формах детьми, людьми. 5) На конце слова после двух согласных ь показывает мягкость последнего: степь, кость. 6) Ь сохраняется, когда второй согласный при изменении слова смягчается: восьмой — восьми, свадьба — свадьбе.'},
 {n:39,l:3,st:5,os:'диктант',task:'Предупредительный диктант. Перед записью найти в тексте слова, где нужно решить, писать ли ь. Записать текст, вставляя ь, где нужно, и выделить сочетания, в которых ь не пишется.',
  body:'На речке. В тёплые ден..ки мы с Колей ходим на реч..ку. Берег там пологий, и мел.. тянется далеко от берега. Тол..ко у ивы начинается глубина. Коля берёт с собой удоч..ку и банку для червей, а я — альбом и карандаши. Пока он ловит рыбу, я рисую волны, лодки и бел..чонка, который прыгает по веткам. Иногда к нам подходит сосед, мал..чик Костя, и рассказывает про свою тётю: она живёт в далёкой деревен..ке, где есть настоящая бан..ка с печкой и вениками. Вечером мы возвращаемся домой уставшие, но довол..ные. Папа спрашивает, скол..ко рыбы поймали. Коля честно отвечает: одну, но очень бол..шую.',
  key:'деньки, речку (без знака), мель, Только, удочку (без знака), бельчонка, мальчик, деревеньке, банька, довольные, сколько, большую.<br>Сочетания без ь: речку (чк), удочку (чк). Мягкий л перед согласным: только, бельчонка, мальчик, довольные, сколько, большую.'},
 {n:40,l:3,st:2,task:'Образовать от данных слов новые слова по образцу. Подчеркнуть ь или сочетание согласных без ь.',
  obr:'День — денёк — деньки; камень — каменщик.',
  body:'1) День, пень, конь, огонь (с суффиксом -к-: деньки…). 2) Камень, гонка, барабан, болеть, кровля, точить (кто это делает?).',
  key:'1) Деньки, пеньки, коньки, огоньки — ь сохраняется (мягкий н перед к). 2) Каменщик, гонщик, барабанщик (нщ — без ь); болельщик, кровельщик, точильщик (мягкий л — с ь).'},
 {n:41,l:3,st:3,task:'Записать пары слов в транскрипции. Указать количество букв и звуков. Сделать вывод о роли ь.',
  obr:'Угол [у́гал] — 4 буквы, 4 звука; уголь [у́гал\'] — 5 букв, 4 звука.',
  body:'Угол — уголь; банка — банька; полка — полька; брат — брать; пыл — пыль; мел — мель.',
  key:'Угол [у́гал] 4 б., 4 зв. — уголь [у́гал\'] 5 б., 4 зв.; банка [ба́нка] 5 б., 5 зв. — банька [ба́н\'ка] 6 б., 5 зв.; полка [по́лка] 5 б., 5 зв. — полька [по́л\'ка] 6 б., 5 зв.; брат [брат] 4 б., 4 зв. — брать [брат\'] 5 б., 4 зв.; кон [кон] 3 б., 3 зв. — конь [кон\'] 4 б., 3 зв.; мел [м\'эл] 3 б., 3 зв. — мель [м\'эл\'] 4 б., 3 зв.<br>Вывод: ь звука не обозначает, он показывает мягкость предыдущего согласного; поэтому в словах с ь букв на одну больше, чем звуков.'},
 {n:42,l:3,st:4,task:'Переписать, вставляя ъ или ь, где нужно. Над каждым знаком указать его работу: р — разделительный, м — мягкость. Выделить сочетания, в которых ь не пишется.',
  obr:'Об..явление (р), бол..шой (м), доч..ка (чк).',
  body:'1. Об..явление повесили у входа. 2. Ребята с..ели по бутерброду и раз..ошлись по домам, а один крикнул: «Брос..те верёвку!» 3. Сегодня морозно: в..юга кружила снег над крышами, и прохожие кутались в тёплые шарфы. 4. Дядя живёт в деревне и каждый год охотится с руж..ём. 5. Ночью шёл дожд.., и к утру река вышла из берегов. 6. Учитель раз..яснил нам правило о сочетании чк, и мы записали слово «доч..ка» в словарик. 7. Каждую весну на школьном дворе сажают дерев..я.',
  key:'1) Объявление; 2) съели, разошлись (без знака), Бросьте; 3) вьюга; 4) ружьём; 5) дождь; 6) разъяснил, дочка (без знака); 7) деревья.<br>Работа знаков: объявление, съели, разъяснил (р, ъ); разошлись — без знака (после приставки о); вьюга, ружьём, деревья (р, ь); бросьте (ь сохраняется перед -те), дождь (м). Без ь: дочка (чк).'},
// ── Урок 4. Ь после шипящих в существительных
 {n:43,l:4,st:1,task:'Распределить слова в два столбика: «моя» (с ь) и «мой» (без ь). Проверить каждое слово подстановкой.',
  obr:'Моя печь — с ь; мой мяч — без ь.',
  body:'Ночь, мяч, рожь, нож, мышь, камыш, дочь, врач, речь, ключ, вещь, плащ, тишь, шалаш, помощь, борщ, глушь, ёрш, печь, товарищ, мелочь, гараж.',
  key:'Моя — с ь: ночь, рожь, мышь, дочь, речь, вещь, тишь, помощь, глушь, печь, мелочь.<br>Мой — без ь: мяч, нож, камыш, врач, ключ, плащ, шалаш, борщ, ёрш, товарищ, гараж.'},
 {n:44,l:4,st:2,task:'Переписать, вставляя ь, где нужно. Рядом с каждым словом написать «мой» или «моя».',
  obr:'Вещ.. — моя вещь; мяч.. — мой мяч.',
  body:'Вещ.., мяч.., гореч.., обруч.., брош.., малыш.., рож.., гараж.., мелоч.., ковш.., тиш.., ёрш.., помощ.., плащ.., дрож.., калач.., молодёж.., стриж.., туш.. (для рисования), туш.. (музыка), полноч.., ландыш.., роскош.., сторож.. .',
  key:'С ь (моя): вещь, ночь, брошь, рожь, мелочь, тишь, помощь, дрожь, молодёжь, тушь, полночь, роскошь.<br>Без ь (мой): мяч, ключ, малыш, гараж, ковш, ёрш, плащ, калач, стриж, туш, ландыш, сторож.'},
 {n:45,l:4,st:2,task:'Образовать от слов форму, которая отвечает на вопрос «много (чего?)». Записать парами. Объяснить, почему ь нет. Отдельно записать слова, у которых в этой форме шипящего на конце нет.',
  obr:'Туча — много туч (без ь); вещь — много вещей.',
  body:'Туча, задача, лужа, крыша, роща, дача, встреча, чаща, груша, каша, ноша; вещь, дочь, речь, печь.',
  key:'Много туч, задач, луж, крыш, рощ, дач, встреч, чащ, груш, каш, нош — в форме «много чего?» ь после шипящего не пишется. Вещь — вещей, дочь — дочерей, речь — речей, печь — печей: здесь конец -ей, шипящего на конце нет.'},
 {n:46,l:4,st:3,task:'Переписать, вставляя ь, где нужно. Над словами с пропуском написать проверочный вопрос: «мой», «моя» или «много чего?».',
  obr:'Полноч.. — моя полночь, с ь; много груш.. — без ь.',
  body:'1. Полноч.. давно прошла. 2. Малыш долго искал свой карандаш.. под кроватью. 3. После дождя во дворе осталось много глубоких луж.., и малыши с радостью прыгали по ним в резиновых сапогах. 4. На краю опушки белел ландыш.. . 5. Сестра сложила всю мелоч.. в копилку. 6. В конце сборника — двадцать трудных задач.. . 7. На столе блестел глубокий ковш.. . 8. Соседка всегда приходит на помощ.. . 9. На ветке висело несколько тяжёлых груш.. . 10. В вечернем саду стояла такая тиш.., что было слышно, как падает яблоко. 11. Врач.. выслушал больного. 12. Кот поймал мыш.. .',
  key:'1) Полночь; 2) карандаш (без знака); 3) луж (без знака); 4) ландыш (без знака); 5) мелочь; 6) задач (без знака); 7) ковш (без знака); 8) помощь; 9) груш (без знака); 10) тишь; 11) Врач (без знака); 12) мышь.<br>Мой: карандаш, ландыш, ковш, врач; моя: полночь, мелочь, помощь, тишь, мышь; много чего: луж, задач, груш.'},
 {n:47,l:4,st:3,task:'Прочитать предложения писателей. Переписать, вставляя ь, где нужно. Объяснить каждое написание подстановкой «мой — моя» или вопросом «много чего?».',
  obr:'Печ.. — моя печь, с ь.',
  body:'1. Ноч.. стояла такая же тихая, как и накануне; но на небе было меньше туч.. – и очертанья кустов, даже высоких цветов, яснее виднелись. (И. С. Тургенев, «Первая любовь») 2. Месяц светил в окно, и луч.. его играл по земляному полу хаты. (М. Ю. Лермонтов, «Герой нашего времени») 3. У берега лежало толстое чёрное бревно, выкинутое водой, и камыш.. вокруг бревна был свежо примят. (Л. Н. Толстой, «Казаки») 4. Печ.. была жарко натоплена, и в ней варился обед, довольно роскошный для бедняков. (М. Ю. Лермонтов, «Герой нашего времени») 5. Когда святого забвения / Кругом недвижная тиш.., — / Ты смотришь в тихом томлении, / Речной раздвинув камыш.. . (А. А. Блок) 6. Я тотчас узнал его, хотя он весь закутался в тёмный плащ.. и шляпу надвинул на лицо. (И. С. Тургенев, «Первая любовь») 7. Казалось, как бы вместе с нею влетел солнечный луч.. в комнату, озаривши вдруг потолок, карниз и тёмные углы её. (Н. В. Гоголь, «Мёртвые души») 8. На том поле, где тогда цвела рож.. и кричали перепела, теперь бродили коровы и спутанные лошади. (А. П. Чехов, «Дом с мезонином») 9. Дрож.. так меня и пробирает. (Н. В. Гоголь, «Женитьба») Пояснения: карниз — выступ стены под потолком.',
  key:'1) Ночь, туч (без знака); 2) луч (без знака); 3) камыш (без знака); 4) Печь; 5) тишь, камыш (без знака); 6) плащ (без знака); 7) луч (без знака); 8) рожь; 9) дрожь.<br>Моя: ночь, печь, тишь, рожь, дрожь; мой: луч, камыш, плащ; много чего: туч.'},
 {n:48,l:4,st:3,task:'Вставить ь, где нужно. Объяснить, как от ь зависит смысл. Составить по предложению с каждым словом пары.',
  obr:'Художник взял чёрную туш.. — тушь (моя), краска для рисования.',
  body:'1. Художник обвёл рисунок чёрной туш..ю. 2. Оркестр сыграл победителям туш.. . 3. Из соседней комнаты доносился детский плач.. . 4. Доч.. нашего соседа стала врачом. 5. На опушке рос молодой дуб, а под ним — ландыш.. . 6. Над полем повисла густая мгла, кругом была глуш.. .',
  key:'1) тушью (моя тушь — краска); 2) туш (мой туш — короткая торжественная музыка); 3) плач (мой плач — без ь); 4) Дочь (моя); 5) ландыш (мой); 6) глушь (моя).<br>Тушь — туш: одинаково звучат, но значат разное; ь показывает, что слово сочетается с «моя».'},
 {n:49,l:4,st:4,task:'Найти и исправить ошибки. Объяснить каждое исправление проверкой. Выписать верно написанные трудные слова.',
  body:'Наш класс ездил в поход. Два дня мы провели в палатках у речки. Сначала мы построили шалашь из веток, потом развели костёр. Дежурный сварил кашу и вкусный борщь. Вечером над озером собралось много тучь, но дождя не было. Моя подруга нашла в траве ежа, а мальчики — ржавый ключь. Учитель рассказал нам о многих интересных встречах в походе и решил с нами несколько задачь по ориентированию. Ночью над лагерем была тишь. Утром нас разбудило пение птиц, а ещё — смешной малышь из соседней палатки.',
  key:'Ошибки: шалашь → шалаш (мой); борщь → борщ (мой); тучь → туч (много чего?); ключь → ключ (мой); задачь → задач (много чего?); малышь → малыш (мой).<br>Верно: тишь (моя). Слова «ежа», «кашу», «встречах» — шипящий не на конце, правило не действует.'},
 {n:50,l:4,st:4,task:'Распределить по группам: 1) ь пишется (моя); 2) ь не пишется (мой); 3) ь не пишется (много чего?); 4) шипящего на конце нет — правило не применяется. Вставить ь, где нужно, и объяснить, к какой группе относится каждое сочетание.',
  obr:'Много встреч.. — 3-я группа.',
  body:'Много встреч.., тёплая встреча, моя реч.., много речей, верный товарищ.., нет задач.., сложная задача, лесная глуш.., вкусный калач.., мало дач.., на даче, своя вещ.., много вещей, речной лещ.. .',
  key:'1) моя речь, лесная глушь, своя вещь; 2) верный товарищ, вкусный калач, речной лещ; 3) много встреч, нет задач, мало дач; 4) тёплая встреча, много речей, сложная задача, на даче, много вещей.'},
 {n:51,l:4,st:5,task:'Тонкость. Объяснить написание. В каких словах проверка «мой — моя» требует внимания и почему?',
  body:'Мышь — малыш; дочь — врач (о женщине); близь — близ; много чудовищ; много кладбищ; ключ (родник) — ключ (от двери); ёрш (рыба) — ёршик; полночь; молодёжь.',
  key:'Мышь — моя, малыш — мой: решает не то, мальчик это или девочка, а как слово сочетается (эта мышь, этот малыш). Дочь — моя; врач — мой, даже если врач — женщина (наш врач пришла). Близь (видна и даль, и близь — моя близь) — с ь, а близ («близ дома» — около) — без ь; шипящего здесь нет, но различие похожее. Много чудовищ, кладбищ — форма «много чего?», без ь (это слова на «оно, моё»). Ключ в обоих значениях — мой, без ь. Ёрш — мой, без ь. Полночь, молодёжь — моя, с ь.'},
 {n:52,l:4,st:5,os:'диктант',task:'Распределительный диктант. Записать слова с шипящими на конце в три столбика: «моя» (с ь), «мой» (без ь), «много чего?» (без ь). Текст для учителя — читать полностью.',
  body:'У дедушки. Вечер опустился на деревню. Над рекой поднялся туман, и в зарослях закричала какая-то птица. Где-то далеко прогудел поезд, а потом снова наступила тиш.. . Дедушка вышел на крыльцо, взял железный фонарь и большой ковш..: перед сном он всегда поливает рассаду. Потом проверяет, заперта ли калитка. Внук выбежал за ним босиком: ему не спалось. Они вдвоём смотрели, как над полем плывут облака и из-за туч.. выглядывают звёзды. Дедушка рассказывал про свою юность: про шалаш.. у реки, про ночную рыбалку и про то, как они с товарищем однажды поймали огромного ерша. Внук слушал, и по спине у него пробегала дрож.. . Над деревней уже наступила полноч.. .',
  key:'Моя (с ь): тишь, дрожь, полночь. Мой (без ь): ковш, шалаш. Много чего (без ь): туч (из-за чего? — из-за туч).<br>Остальные слова с шипящими (товарищем, ерша) — шипящий не на конце.'},
 {n:53,l:4,st:2,task:'Подобрать и записать по пять существительных с шипящими на конце в каждую группу: «моя» (с ь) и «мой» (без ь). Использовать разные шипящие: ж, ш, ч, щ.',
  obr:'Моя тушь, мой лещ.',
  body:'Подсказки для поиска: животные, растения, предметы в доме, явления природы, люди по профессии.',
  key:'Примерно. Моя: рожь, мышь, ночь, печь, помощь, тушь, брошь, мелочь, речь, вещь. Мой: ёж, нож, камыш, ёрш, грач, врач, ключ, плащ, борщ, лещ.'},
 {n:54,l:4,st:3,task:'Записать слова в транскрипции. Сравнить звучание слов с ь и без ь на конце. Сделать вывод: обозначает ли ь мягкость после шипящих?',
  obr:'Мышь [мыш] — камыш [камы́ш].',
  body:'Рожь — нож; дочь — врач; мышь — камыш; помощь — плащ; тишь — малыш.',
  key:'Рожь [рош] — нож [нош]; дочь [доч\'] — врач [врач\']; мышь [мыш] — камыш [камы́ш]; помощь [по́мащ\'] — плащ [плащ\']; тишь [т\'иш] — малыш [малы́ш].<br>Вывод: после шипящих ь мягкости не обозначает: ж, ш звучат твёрдо, ч, щ — мягко с ь и без ь. Ь здесь — только знак того, к какой группе относится слово.'},
 {n:55,l:4,st:4,task:'Прочитать предложения. Вставить ъ или ь, где нужно. Объяснить каждое написание. Указать, в каких словах шипящий стоит на конце, но ь не нужен, и почему; какой знак в этих предложениях не связан с шипящими.',
  body:'1. Рож.., овёс, ячмень и гречиха родятся на тучных его нивах. (А. С. Пушкин, «История села Горюхина») 2. Кончимте скорее; неравно кто-нибудь проедет по ущел..ю — и нас увидят. (М. Ю. Лермонтов, «Герой нашего времени») 3. Ко мне навстречу ключ.. бежит — / Он в дол спешит на новоселье, — / Я лезу вверх, где ель стоит. (Ф. И. Тютчев) 4. Покосившаяся избёнка, / Плач.. овцы, и вдали на ветру / Машет тощим хвостом лошадёнка, / Заглядевшись в неласковый пруд. (С. А. Есенин) 5. Если бы мелоч.., послать бы на рынок и купить хоть бы сайку. (Н. В. Гоголь, «Ревизор») 6. Экая славная вещ.. сон, подумаешь! (И. С. Тургенев, «Яков Пасынков») Пояснения: дол — долина; ключ — родник; нива — поле; сайка — небольшая булка.',
  key:'1) Рожь; 2) ущелью; 3) ключ (без знака); 4) Плач (без знака); 5) мелочь; 6) вещь.<br>1) рожь — моя. 2) ущелью — разделительный ь. 3) ключ — мой (родник), без ь. 4) плач — мой плач, без ь. 5) мелочь — моя. 6) вещь — моя.'},
 {n:56,l:4,st:3,task:'Переписать текст, вставляя ъ или ь, где нужно. Объяснить написание слов с шипящими на конце.',
  obr:'Верный товарищ.. — мой товарищ, без ь.',
  body:'Мой друг. У меня есть верный товарищ.. — пёс Шарик. Каждое утро он приносит мне в зубах карандаш..: зовёт гулять. Мы выходим из под..езда и бежим к реч..ке. Там, у старой груш..и, Шарик знает каждый куст. Однажды он нашёл в траве чью-то брош.. и гордо принёс её мне. Мы долго искали хозяйку, и наконец пожилая соседка узнала свою вещ.. . В благодарность она угостила нас тёплым калач..ом. А вечером, когда приходит пора спать, Шарик сторожит наш двор и не боится ни ливня, ни грома.',
  key:'товарищ (без знака), карандаш (без знака), подъезда, речке (без знака), груши (без знака), брошь, вещь, калачом (без знака).<br>Товарищ, карандаш — мой; брошь, вещь — моя; груши, калачом — шипящий не на конце; подъезда — ъ после приставки; речке — чк, без ь.'},
// ── Урок 5. Ь после шипящих: глаголы, наречия, частицы
 {n:57,l:5,st:1,task:'Выписать слова в два столбика: с ь после шипящего и без ь. К каждому слову указать часть речи (для глагола — форму: неопределённая форма, 2-е лицо, повелительное наклонение).',
  obr:'Беречь — глагол в неопределённой форме (что делать?), с ь; могуч — краткое прилагательное (каков?), без ь.',
  body:'Беречь, свеж, настежь, пишешь, режь, хорош, замуж, лишь, могуч, вскачь, учишься, спрячь, горяч, уж, прочь, стеречь, колюч, несёшь, сплошь, невтерпёж.',
  key:'С ь: беречь (неопределённая форма), настежь (наречие), пишешь (2-е лицо), режь (повелительное наклонение), лишь (частица), вскачь (наречие), учишься (2-е лицо), спрячь (повелительное наклонение), прочь (наречие), стеречь (неопределённая форма), несёшь (2-е лицо), сплошь (наречие).<br>Без ь: свеж, хорош, могуч, горяч, колюч (краткие прилагательные); замуж, уж, невтерпёж (исключения).'},
 {n:58,l:5,st:2,task:'1) Переписать, вставляя ь, где нужно. Доказать вопросом «что делать?» или «что сделать?», что это глаголы в неопределённой форме. 2) Составить словосочетания с тремя словами.',
  obr:'Подстрич.. куст — подстричь (что сделать?).',
  body:'Береч.. природу, стереч.. сад, леч.. спать, помоч.. сестре, жеч.. костёр, печ.. булки, стрич..ся у мастера, увлеч..ся рисованием, отвлеч.. внимание, береч..ся простуды, привлеч.. читателей, испеч.. торт.',
  key:'1) Беречь, стеречь, лечь, помочь, жечь, печь, стричься, увлечься, отвлечь, беречься, привлечь, испечь. Во всех словах ь после ч: это глаголы в неопределённой форме (что делать? что сделать?); ь сохраняется и перед -ся.<br>2) Примерно: беречь здоровье, помочь бабушке, испечь блины.'},
 {n:59,l:5,st:2,task:'Образовать от данных глаголов форму 2-го лица единственного числа (ты что делаешь? ты что сделаешь?). Записать с местоимением «ты». Подчеркнуть ь.',
  obr:'Писать — ты пишешь; учиться — ты учишься.',
  body:'Писать, нести, увидеть, рисовать, построить, учиться, смеяться, одеться, решить, мечтать, вернуться, прыгнуть, спрятаться, подарить, улыбаться.',
  key:'Ты пишешь, несёшь, увидишь, рисуешь, построишь, учишься, смеёшься, оденешься, решишь, мечтаешь, вернёшься, прыгнешь, спрячешься, подаришь, улыбаешься — на конце после ш пишется ь, перед -ся он сохраняется.'},
 {n:60,l:5,st:2,task:'Образовать от данных глаголов форму повелительного наклонения (просьба или приказ) к одному человеку и к нескольким людям. Записать парами. Подчеркнуть ь.',
  obr:'Резать — режь, режьте.',
  body:'Резать, прятать, плакать (с не), мазать (на-), утешить, есть, спрятаться, утешиться, отрезать.',
  key:'Режь — режьте; спрячь — спрячьте; не плачь — не плачьте; намажь — намажьте; утешь — утешьте; ешь — ешьте; спрячься — спрячьтесь; утешься — утешьтесь; отрежь — отрежьте. Ь после шипящего сохраняется перед -те и -ся.'},
 {n:61,l:5,st:3,task:'Переписать, вставляя ь, где нужно. Над словами с пропуском написать вопрос и часть речи. Объяснить, почему в кратких прилагательных ь нет.',
  obr:'Мёд тягуч.. — каков? тягуч (краткое прилагательное от «тягучий»): без ь.',
  body:'1. Мёд тягуч.. . 2. Чай слишком горяч.., его нельзя пить сразу. 3. Мороз сегодня трескуч..! 4. Над рекой высился могучий дуб, и ствол его был так могуч.., что трое ребят не могли его обхватить. 5. Ты отлично умееш.. кататься на коньках. 6. Кустарник колюч.. . 7. Крапива жгуч.., её не стоит трогать голыми руками. 8. Голос у певицы удивительно певуч.. . 9. Ты так быстро бежиш.., что я не успеваю! 10. Бор вокруг дремуч.. и тёмен.',
  key:'1) тягуч (без знака); 2) горяч (без знака); 3) трескуч (без знака); 4) могуч (без знака); 5) умеешь; 6) колюч (без знака); 7) жгуч (без знака); 8) певуч (без знака); 9) бежишь; 10) дремуч (без знака).<br>Краткие прилагательные (каков?) — тягуч, горяч, трескуч, могуч, колюч, жгуч, певуч, дремуч: без ь. Умеешь и бежишь (глаголы 2-го лица единственного числа) — с ь.'},
 {n:62,l:5,st:3,task:'Переписать, вставляя ь, где нужно. Задать вопрос к слову с пропуском и указать часть речи. Выделить три наречия-исключения.',
  obr:'Окна открыты настеж.. — как? настежь, наречие, с ь.',
  body:'1. Окна открыты сплош.. во всём здании. 2. Всадники умчались вскач.. . 3. Рисунок получился точ..-в-точ.. как на картине. 4. Уж.. полночь, а Петя ещё читает. 5. Соседка, которую мы знаем с детства, вышла замуж.. в прошлом году. 6. Пёс бросился проч.. от сердитого гуся. 7. Ждать было невтерпёж..: так хотелось открыть подарок! 8. Мальчик, который бежал по узкой тропинке к автобусу, споткнулся и упал навзнич.. в мягкий снег. 9. Он взмахнул рукой наотмаш.. . 10. После долгого пути идти дальше стало невмоч.. .',
  key:'1) сплошь; 2) вскачь; 3) точь-в-точь; 4) Уж (без знака); 5) замуж (без знака); 6) прочь; 7) невтерпёж (без знака); 8) навзничь; 9) наотмашь; 10) невмочь.<br>Исключения без ь: уж, замуж, невтерпёж. Все слова — наречия. Наречия-исключения без ь: уж, замуж, невтерпёж; остальные наречия — с ь.'},
 {n:63,l:5,st:3,task:'Прочитать предложения писателей. Переписать, вставляя ь, где нужно. Задать вопрос к словам с пропуском и указать часть речи.',
  obr:'Метёш.. — ты что делаешь? метёшь, глагол 2-го лица единственного числа, с ь.',
  body:'1. Да ты, Захар Трофимыч, — начала Анисья, вдруг выглянув из другой комнаты, — напрасно сначала метёш.. пол, а потом со столов сметаеш..: пыль-то опять и насядет… (И. А. Гончаров, «Обломов») 2. То ли дело, на зорьке выйдеш.., местечко выбереш.., камыш.. прижмёш.., сядеш.. и сидиш.., добрый молодец, дожидаешься. (Л. Н. Толстой, «Казаки») 3. Кого не любиш.., кто не хорош.., с тем не обмакнёш.. хлеба в солонку. (И. А. Гончаров, «Обломов») 4. Сапоги мои набрали воды и при каждом шаге громко хлюпали; становилось невмоч.. тянуть их за собою. (А. И. Куприн, «Олеся») 5. Я поглядел, рассмеялся, встряхнулся – и грустные думы тотчас отлетели проч..: отвагу, удаль, охоту к жизни почувствовал я. (И. С. Тургенев) 6. Андрей пустил измученную тройку вскач.. и действительно с треском подкатил к высокому крылечку. (Ф. М. Достоевский, «Братья Карамазовы») 7. Как новый, ранний снег / Всегда и чист и свеж..! (А. А. Фет) Пояснения: на зорьке — на рассвете.',
  key:'1) метёшь, сметаешь; 2) выйдешь, выберешь, камыш (без знака), прижмёшь, сядешь, сидишь; 3) любишь, хорош (без знака), обмакнёшь; 4) невмочь; 5) прочь; 6) вскачь; 7) свеж (без знака).<br>Глаголы 2-го лица единственного числа (ты что делаешь?) — метёшь, сметаешь, выйдешь, выберешь, прижмёшь, сядешь, сидишь, любишь, обмакнёшь (с ь); наречия (как? куда?) — невмочь, прочь, вскачь (с ь); краткие прилагательные (каков?) — хорош, свеж (без ь); камыш — существительное, мой (урок 4), без ь.'},
 {n:64,l:5,st:3,task:'Вставить ь, где нужно. Объяснить, почему одинаково звучащие слова пишутся по-разному. С каждым словом пары составить своё предложение.',
  obr:'Не реж.. палец! — повелительное наклонение, с ь; мой ковш.. — существительное, без ь.',
  body:'1. Не плач..! 2. Из-за двери, за которой осталась сестрёнка, ещё долго слышался обиженный плач.. . 3. Мама учит сестру печ.. блины. 4. В деревенской избе, где выросла мать, до сих пор стоит большая русская печ.. . 5. Мы пришли помоч.. соседям. 6. Спасибо за помощ..! 7. Ты всегда так красиво и аккуратно пишеш.. в тетради, что учитель ставит тебя в пример. 8. Цветной карандаш.. сломался.',
  key:'1) плачь; 2) плач (без знака); 3) печь; 4) печь; 5) помочь; 6) помощь; 7) пишешь; 8) карандаш (без знака).<br>Не плачь — глагол в повелительном наклонении (с ь), плач — существительное, мой (без ь); печь (глагол, что делать?) и печь (существительное, моя) — обе с ь; помочь (глагол, что сделать?) и помощь (существительное, моя) — обе с ь, но корни звучат и пишутся по-разному (ч — щ); пишешь (глагол 2-го лица единственного числа) — с ь, карандаш — существительное, мой, без ь.'},
 {n:65,l:5,st:4,task:'Найти и исправить ошибки в употреблении ь после шипящих. Объяснить каждое исправление: назвать часть речи (форму) и задать вопрос.',
  body:'Дорогая Оля! Ты, наверное, не знаеш, как я по тебе скучаю. Вчера мама учила меня печ пирожки, но тесто получилось слишком мягким. Она сказала: «Не плачь, в следующий раз пирог будет хорошь!» А ещё я помогала папе стереч наш сад: ночью мы по очереди сидели у калитки. Ты сообщаешь, что у тебя всё хорошо, но ветер в деревне колючь и холоден. Пожалуйста, не забывай беречься и одевайся теплее. Скоро я приеду, и мы с тобой испечём настоящий торт. Жду не дождусь — прямо невтерпёжь!',
  key:'Ошибки: знаеш → знаешь (2-е лицо единственного числа); печ → печь (неопределённая форма); хорошь → хорош (краткое прилагательное); стереч → стеречь (неопределённая форма); колючь → колюч (краткое прилагательное); невтерпёжь → невтерпёж (исключение).<br>Верно: не плачь (повелительное наклонение), сообщаешь (2-е лицо единственного числа), беречься (неопределённая форма; ь перед -ся сохраняется).'},
 {n:66,l:5,st:4,task:'Распределить словосочетания по столбикам: «пишется ь» и «не пишется ь». Вставить ь, где нужно. У каждого слова с пропуском указать часть речи и причину (мой, моя, много чего?, неопределённая форма, 2-е лицо, повелительное наклонение, краткое прилагательное, наречие, частица, исключение).',
  obr:'Сильная дрож.. — моя, с ь.',
  body:'Сильная дрож.., острый нож.., реж.. аккуратно, много луж.., ты ляжеш.. спать, сыр пахуч.., упасть навзнич.., лиш.. бы успеть, много встреч.., надо береч.., спряч..ся за угол, лес дремуч.., мчаться вскач.., лесная глуш.., звонкий стриж.., уж.. поздно.',
  key:'Пишется ь: сильная дрожь (существительное, моя), режь аккуратно (повелительное наклонение), ты ляжешь (2-е лицо), упасть навзничь (наречие), лишь бы (частица), надо беречь (неопределённая форма), спрячься (повелительное наклонение, ь перед -ся), мчаться вскачь (наречие), лесная глушь (существительное, моя).<br>Не пишется ь: острый нож (мой), много луж, много встреч (много чего?), сыр пахуч, лес дремуч (краткие прилагательные), уж поздно (исключение), звонкий стриж (мой).'},
 {n:67,l:5,st:5,task:'Тонкость. Объяснить написание. Где правило о ь после шипящих применяется не напрямую или не применяется вовсе?',
  body:'Ляг — лягте; ты ешь — ешь кашу!; уж (змея) — уж (уже); замуж — за мужа; невтерпёж; вперемешку; нараспашку; лишь — лишний; точь-в-точь; наотмашь.',
  key:'Ляг, лягте (от «лечь») — на конце г, не шипящий: ь не нужен, правило не действует. Ты ешь (2-е лицо) и ешь! (повелительное наклонение) — оба с ь. Уж (змея) — мой, без ь; уж (уже, ведь) — исключение без ь. Замуж — исключение, исторически «за мужа»; невтерпёж — исключение. Вперемешку, нараспашку — кончаются на у, шипящего на конце нет. Лишь — частица, с ь; в «лишний» шипящий не на конце. Точь-в-точь — наречие, обе части с ь. Наотмашь — наречие, с ь.'},
 {n:68,l:5,st:5,os:'диктант',task:'Выборочный диктант. Выписать из текста слова с шипящими на конце, разделив их на две группы: с ь и без ь. Объяснить каждое написание. (Учитель читает текст полностью.)',
  body:'Совет младшему брату. Если хочешь стать умелым рыбаком, слушай меня. Вставать надо рано: на рассвете клюёт охотнее всего. Ты берёшь удочку, банку с червями, карандаш и тихо, без шума, идёшь к реке. Сядь на берегу, где трава погуще, и жди. Не спеши и не кричи: рыба пугается. Если сорвётся, не огорчайся — так бывает у всех. Улов сразу прячь в сумку. Не бросай снасти как попало. Когда клюнет, подсекай резко, но не тяни слишком сильно, иначе леска лопнет. А потом неси улов домой — пусть все увидят, что ты рыбак хоть куда! Только помни: удача приходит лишь к тем, кто умеет ждать. И не забудь, что вечером мама будет печь пирог с той самой рыбой.',
  key:'С ь: хочешь, берёшь, идёшь (2-е лицо единственного числа); прячь (повелительное наклонение); лишь (частица); печь (неопределённая форма).<br>Без ь: карандаш (мой).'},
 {n:69,l:5,st:4,task:'Работа с предложениями писателей. Вставить ь, где нужно. Выписать все слова с шипящими на конце и распределить по группам: глаголы 2-го лица (ты что делаешь?), наречия (как? куда?), краткие прилагательные (каков?), существительные (мой — моя). Найти слова, где ь пишется по правилу урока 3.',
  body:'1. Как взбежиш.. по лестнице к себе на четвёртый этаж.. — скажеш.. только кухарке: «На, Маврушка, шинель…» (Н. В. Гоголь, «Ревизор») 2. Ему было под пятьдесят лет, но он был очень свеж.., только красил усы и прихрамывал немного на одну ногу. (И. А. Гончаров, «Обломов») 3. Около настеж.. открытых ворот уже собралась толпа и смотрела во двор. (А. П. Чехов, «В овраге») 4. Я повернулся и пошёл от него проч.. . (М. Ю. Лермонтов, «Герой нашего времени») 5. Подходиш.. ближе, глядиш.. – точно Иван Петрович! (Н. В. Гоголь, «Мёртвые души») 6. Завтрак был очень хорош..; я совсем об..елся. (Н. В. Гоголь, «Ревизор») 7. Если бы мелоч.., послать бы на рынок и купить хоть бы сайку. (Н. В. Гоголь, «Ревизор»)',
  key:'1) взбежишь, этаж (без знака), скажешь; 2) свеж (без знака); 3) настежь; 4) прочь; 5) Подходишь, глядишь; 6) хорош (без знака), объелся; 7) мелочь.<br>Глаголы 2-го лица — взбежишь, скажешь, подходишь, глядишь; наречия — настежь, прочь; краткие прилагательные — свеж, хорош; существительные: мой — этаж; моя — мелочь. Ь мягкости (урок 3): только, шинель, очень (на конце), пятьдесят (в середине числа — запомнить). Ъ — объелся (приставка об-).'},
 {n:70,l:5,st:2,task:'Составить пять советов младшему брату или сестре, используя слова: не прячь, спрячь, беречь, ешь, режь. Затем записать по одному предложению с краткими прилагательными (каков?): певуч, могуч, горяч.',
  obr:'Не прячь ключи далеко. Ёжик колюч — не трогай его руками.',
  body:'Слова: не прячь, спрячь, беречь, ешь, режь; певуч, могуч, горяч.',
  key:'Примерно: Не прячь дневник от родителей. Спрячь конфеты до обеда. Нужно беречь книги. Ешь кашу, она полезная. Режь хлеб осторожно. Голос у неё певуч. Старый дуб могуч. Чай горяч. Проверка: в повелительном наклонении и в неопределённой форме глагола — ь, в кратких прилагательных — без ь.'},
// ── Повторение
 {n:71,l:6,st:3,task:'Переписать, вставляя ъ или ь, где нужно. Объяснить каждое написание: какое правило действует.',
  obr:'Под..ём — ъ после приставки; тиш.. — моя тишь.',
  body:'1. Под..ём оказался крутым. 2. Весь вечер на улице выл ветер и гнул к земле сухой бур..ян, а к утру небо прояснилось. 3. Мы с..ели по яблоку и пошли дальше. 4. Ты так громко смеёш..ся, что слышно на улице. 5. Ты пишеш.. без ошибок. 6. Сосед протянул руку и взял со стола свой ключ.. . 7. В роще было тихо, тол..ко где-то вдалеке хлопали крыл..я. 8. Брос..те канат! 9. На столе лежало несколько спелых груш.. . 10. Учитель раз..яснил ошибки в диктанте. 11. Мороз крепчал, и стоять на месте стало невмоч.. . 12. Этот перец жгуч.. .',
  key:'1) Подъём; 2) бурьян; 3) съели; 4) смеёшься; 5) пишешь; 6) ключ (без знака); 7) только, крылья; 8) Бросьте; 9) груш (без знака); 10) разъяснил; 11) невмочь; 12) жгуч (без знака).'},
 {n:72,l:6,st:4,task:'Прочитать предложения писателей. Вставить ъ или ь, где нужно. Над каждым словом с пропуском указать правило цифрой: 1 — ъ после приставки; 2 — разделительный ь; 3 — ь мягкости; 4 — ь после шипящих (или его отсутствие).',
  body:'1. Карета с громом вз..ехала на мост через Бугуруслан, и тут тол..ко я догадался, что мы так близко от нашего милого Багрова. (С. Т. Аксаков, «Детские годы Багрова-внука») 2. Зачем крутится ветр в овраге, / Под..емлет лист и пыл.. несёт, / Когда корабл.. в недвижной влаге / Его дыхан..я жадно ждёт? (А. С. Пушкин, «Египетские ночи») 3. Сентябрь холодный бушевал, / С дерев..ев ржавый лист валился, / Ден.. потухающий дымился, / Сходила ноч.., туман вставал. (Ф. И. Тютчев) 4. Сегодня тепло, можно окна держать настеж.., а берёзы ещё не распускались. (А. П. Чехов, «Три сестры») 5. Я и думать забыл про холодную ноч.., — / До костей и до сердца прогрело; / Что смущало, колеблясь умчалося проч.., / Будто искры в дыму улетело. (А. А. Фет) 6. Наконец я стал об..яснять ей мои предположения. (А. С. Пушкин, «Капитанская дочка») Пояснения: подъемлет — поднимает (устар.); ветр — ветер.',
  key:'1) взъехала, только; 2) Подъемлет, пыль, корабль, дыханья; 3) деревьев, День, ночь; 4) настежь; 5) ночь, прочь; 6) объяснять.<br>Правила: взъехала, подъемлет, объяснять — 1; деревьев, дыханья — 2; только, пыль, корабль, день — 3; ночь (моя), настежь, прочь (наречия) — 4.'},
 {n:73,l:6,st:4,task:'Задание для абитуриентов. Указать варианты ответов, в которых во всех словах одного ряда пропущена одна и та же буква. Записать номера ответов и слова с пропусками.',
  body:'Ряды:<br>1) под..ём, с..ёмка, пред..юбилейный, из..ятие, меж..ярусный;<br>2) бур..ян, стат..я, об..явление;<br>3) с..экономить, без..аварийный;<br>4) сем..я, бул..он, друз..я, плат..е, пер..я, мурав..и, коп..ё;<br>5) двух..ядерный, раз..яснить, ин..екция, трёх..ярусный, сверх..яркий, четырёх..ядерный;<br>6) интерв..ю, из..ян, солов..и.',
  key:'Ответ: 1, 4, 5. В ряду 1 — ъ (подъём, съёмка, предъюбилейный, изъятие, межъярусный); в ряду 4 — ь (семья, бульон, друзья, платье, перья, муравьи, копьё); в ряду 5 — ъ (двухъядерный, разъяснить, инъекция, трёхъярусный, сверхъяркий, четырёхъядерный). Ряд 2: бурьян, статья (ь) — объявление (ъ). Ряд 3: сэкономить, безаварийный — знак не пишется. Ряд 6: интервью, соловьи (ь) — изъян (ъ).'},
 {n:74,l:6,st:4,task:'Задание для абитуриентов. Указать варианты ответов, в которых во всех словах ряда на месте пропуска пишется ь. Записать номера ответов и объяснить написание.',
  body:'Ряды:<br>1) тёмная полноч.., сплош.. туман, уж.. вечер;<br>2) береч.. природу, упасть навзнич.., сильная дрож.., ты ляжеш.. спать;<br>3) лес дремуч.., лиш.. бы успеть;<br>4) похож.. на отца, сыр пахуч..;<br>5) ты пишеш.., спряч..ся за ширму, махнуть наотмаш..;<br>6) тяжёлый багаж.., зоркий стриж.. .',
  key:'Ответ: 2, 5. Ряд 2: беречь (неопределённая форма), навзничь (наречие), дрожь (существительное, моя), ляжешь (2-е лицо). Ряд 5: пишешь (2-е лицо), спрячься (повелительное наклонение), наотмашь (наречие). Ряд 1: полночь, сплошь — с ь, уж — исключение. Ряд 3: дремуч (краткое прилагательное) — без ь. Ряд 4: похож, пахуч (краткие прилагательные) — без ь. Ряд 6: багаж, стриж (мой) — без ь.'},
 {n:75,l:6,st:5,os:'сочинение',task:'Сочинение-миниатюра «Зимний вечер» (6–8 предложений). Использовать не меньше двух слов с разделительным ъ, трёх слов с разделительным ь и четырёх слов с шипящими на конце (с ь и без ь). Подчеркнуть эти слова и объяснить их написание.',
  body:'Слова для справки: подъезд, съехать, объявить, вьюга, друзья, платье, ночь, тишь, лещ, грач, лечь, хорош, свеж.',
  key:'Образец: Вечером над городом закружилась вьюга. Я надела тёплое платье и вышла к подъезду. Мы с друзьями решили съехать с горки, пока не стемнело. Ночь наступила быстро, и во дворе стало тихо: такая тишь бывает только зимой. Воздух был свеж и чист. Дома мы выпили горячий чай, и каждый сказал: «Пора лечь пораньше». Вечер был хорош!<br>Критерии: нужное число слов каждой группы, верное написание, объяснение (ъ — после приставки; ь — внутри слова; ночь, тишь — существительные, моя; свеж, хорош — краткие прилагательные; лечь — неопределённая форма глагола; платье, друзья — разделительный ь).'},
 {n:76,l:6,st:5,os:'диктант',task:'Контрольный диктант с грамматическим заданием. Записать текст. Задание: 1) обозначить приставку в словах с ъ; 2) над словами с шипящими на конце указать часть речи и проверку (мой, моя, каков?, как?, ты что делаешь?).',
  body:'Каникулы у дедушки. На каникулы я всегда уезжаю к дедушке в деревню. Едва автобус останавливается у под..ёма в гору, я вижу знакомую дорогу, высокие дерев..я и дедушкин двор. Калитка распахнута, и меня уже ждут. Дедушка обнимает меня и говорит: «Ты так вырос, что скоро меня обгониш..!» Вечером мы пьём чай с малиновым вареньем и мёдом. Мёд тягуч.., варенье сладкое, и в комнате пахнет ватрушками. Дед рассказывает, как в детстве с друзьями ходил за грибами и однажды заблудился. Только затемно их нашли по голосам. Потом он смеётся и вспоминает, как упал навзнич.. прямо в сугроб. Я слушаю, а за окном так тихо, что слышно, как в саду падают яблоки. Перед сном дедушка раз..ясняет мне, где лежит мой фонарик и новый карандаш.. . Утром мы пойдём на речку, и я наконец научусь ловить рыбу.',
  key:'подъёма, деревья, обгонишь, тягуч (без знака), навзничь, разъясняет, карандаш (без знака).<br>Приставки: под-ъ-ём, раз-ъ-ясняет. Навзничь — наречие (как?); обгонишь — глагол 2-го лица (ты что сделаешь?); тягуч — краткое прилагательное (каков?); карандаш — существительное, мой.'},
 {n:77,l:6,st:3,task:'Составить и заполнить таблицу «Ъ и Ь»: где пишется знак, перед какими буквами, примеры (по три), где не пишется (по два примера). Строки: разделительный ъ; разделительный ь; ь мягкости; ь после шипящих (с ь); после шипящих без ь.',
  obr:'Разделительный ъ | после приставки на согласный, после двух-, трёх-, четырёх- | перед е, ё, ю, я | подъём, съёмка, трёхъярусный | не пишется: безопасный, детясли.',
  body:'Слова для справки: подъём, безопасный, вьюга, друзья, бульон, тетрадь, пальцы, дочка, глушь, лечь, пишешь, прочь, сторож, груш, певуч, уж.',
  key:'Разделительный ъ — после приставки на согласный, после двух-, трёх-, четырёх-, после иноязычных приставок; перед е, ё, ю, я: подъезд, съёмка, адъютант; не пишется: безопасный, детясли.<br>Разделительный ь — внутри слова (корень, перед окончанием) перед е, ё, ю, я, и; в заимствованных — перед о: вьюга, друзья, бульон; не пишется после приставки: подъезд.<br>Ь мягкости — на конце и перед твёрдым согласным, мягкий л перед согласным: письмо, пальцы, конь; не пишется: дочка, каменщик.<br>Ь после шипящих пишется: в существительных ж. р. (моя ночь); в глаголах — в неопределённой форме (беречь), во 2-м лице (пишешь), в повелительном наклонении (режь); в наречиях (настежь); в частицах (лишь).<br>Без ь: в существительных м. р. (мой сторож) и в родительном падеже множественного числа (много туч); в кратких прилагательных (колюч); в наречиях-исключениях (уж, замуж, невтерпёж).'},
 {n:78,l:6,st:4,task:'Комплексное задание. 1) Записать слова в транскрипции. 2) Указать количество букв и звуков. 3) Объяснить, какую работу выполняет ъ или ь в каждом слове.',
  body:'Вьюга, объём, ночь, мяч, письмо, семья, брошь, съел.',
  key:'Вьюга [в\'й\'у́га] — 5 букв, 5 звуков, ь разделительный. Объём [абй\'о́м] — 5 букв, 5 звуков, ъ разделительный. Ночь [ноч\'] — 4 буквы, 3 звука, ь после шипящего мягкости не обозначает (моя ночь). Мяч [м\'ач\'] — 3 буквы, 3 звука, без ь (мой мяч). Письмо [п\'ис\'мо́] — 6 букв, 5 звуков, ь мягкости. Семья [с\'им\'й\'а́] — 5 букв, 5 звуков, ь разделительный. Брошь [брош] — 5 букв, 4 звука, ь после шипящего. Съел [сй\'э́л] — 4 буквы, 4 звука, ъ разделительный.'},
 {n:79,l:6,st:5,os:'работа с текстом',task:'Работа с текстом. Прочитать отрывки. 1) Выписать все слова с ъ и ь, распределив их по группам: ъ после приставки; разделительный ь; ь мягкости; ь после шипящих. 2) Найти слова с шипящими на конце без ь и объяснить.',
  body:'1. Иван Иванович очень сердится, если ему попадётся в борщ муха: он тогда выходит из себя — и тарелку кинет, и хозяину достанется. (Н. В. Гоголь, «Повесть о том, как поссорился Иван Иванович с Иваном Никифоровичем») 2. Он подошёл к её дому и посмотрел через палисадник: окна были открыты настежь, огня не было. (А. П. Чехов, «Дуэль») 3. Сквозь постоянный шум ветра чудились мне невдалеке слабые звуки: топор осторожно стучал по сучьям, колёса скрыпели, лошадь фыркала… (И. С. Тургенев, «Записки охотника») 4. Уже подъезжая к нему, я увидел, что это совсем другое, совсем не то, что видал я прежде. (С. Т. Аксаков, «Детские годы Багрова-внука») 5. Дед засеял баштан на самой дороге и перешёл жить в курень; взял и нас с собою гонять воробьёв и сорок с баштану. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») Пояснения: скрыпели — скрипели (устар.); баштан — бахча, поле с арбузами и дынями; курень — шалаш, лёгкая постройка.',
  key:'1) Ъ после приставки: подъезжая. Разделительный ь: сучьям, воробьёв. Ь мягкости: очень, сквозь, лошадь, жить, курень, гонять. Ь после шипящих: настежь (наречие).<br>2) Без ь: борщ (мой борщ). В слове «подошёл» шипящий не на конце — правило не действует.'},
 {n:80,l:6,st:3,task:'Словарный диктант. Записать слова под диктовку учителя, вставляя ъ или ь, где нужно. Обменяться тетрадями и проверить друг друга по ключу.',
  obr:'Объявление — ъ перед я; бурьян — ь внутри слова.',
  body:'Объявление, бурьян, съёмка, бульон, двухъярусный, безопасный, деньки, дочка, болельщик, каменщик, роскошь, ландыш, много задач, лечь, учишься, режь, прочь, замуж, могуч, лишь, павильон, интервью, адъютант, детясли.',
  key:'Объявление, бурьян, съёмка, бульон, двухъярусный, безопасный, деньки, дочка, болельщик, каменщик, роскошь, ландыш, много задач, лечь, учишься, режь, прочь, замуж, могуч, лишь, павильон, интервью, адъютант, детясли.'},
 {n:81,l:6,st:4,task:'Повторение. Вставить пропущенные буквы: безударные гласные и согласные в корне, ъ и ь. Объяснить каждое написание (проверочное слово или правило).',
  obr:'З..мой на с..ёмной даче — зимой (зи́мы), съёмной (ъ после приставки с-).',
  body:'Об..ёмная к..робка, з..лёная лу..жайка, м..лчаливый сосед, з..мой на с..ёмной даче, с..ёмка фил..ма, ре..кий дождь и тёмная полноч.., сл..дкий мёд тягуч.., бере..зовая роща, тр..вянистый бере..г, ре..ка в д..лине.',
  key:'Объёмная (ъ — приставка об-) коробка (словарное слово); зелёная (зе́лень) лужайка (лу́жи — ж); молчаливый (мо́лча) сосед; зимой (зи́мы) на съёмной (ъ после приставки) даче; съёмка (ъ) фильма (мягкий л); редкий (ре́док, д) дождь и тёмная полночь (моя); сладкий (сла́док, д) мёд тягуч (каков?); берёзовая (берёза — з) роща; травянистый (тра́вы) берег (берега́ — г); река (ре́ки) в долине (дол).'},
 {n:82,l:6,st:4,task:'Распределить слова по функции знака ь: 1) разделительный; 2) обозначает мягкость на конце; 3) обозначает мягкость в середине; 4) пишется после шипящего (мягкости не обозначает). Вставить ь, где нужно; слова без ь выписать отдельно с объяснением.',
  body:'Сол.., с сол..ю, пал..то, лис..и, точ..ный, ступен..ки, сыновь..я, руч..ка, меч.., стереч.., бел..ё, гус.., ал..бом, мыш.., ёрш.. .',
  key:'1) разделительный: солью, лисьи, сыновья, бельё; 2) мягкость на конце: соль, гусь; 3) мягкость в середине: пальто, ступеньки, альбом; 4) после шипящего: стеречь, мышь.<br>Без ь: точный, ручка (чк, чн), меч, ёрш (мой).'}
];
const ZN2_LNAMES=['',...ZN2.lessons.map(l=>l.t),'Повторение'];
const ZN2_BOOKREF={1:'Розенталь, «Русский язык» (пособие), раздел «Разделительные ъ и ь», упр. 79',2:'Розенталь, «Русский язык» (пособие), раздел «Разделительные ъ и ь», упр. 79; § 1, упр. 1',3:'Розенталь, «Русский язык» (пособие), § 1, упр. 2–3',4:'Сидорова, «Русский язык для абитуриентов», тема 5, тест № 3 (задания 5–8)',5:'Розенталь, «Русский язык» (пособие), § 47, упр. 219–220; § 54, упр. 255',6:'Сидорова, «Русский язык для абитуриентов», тема 5, тест № 3'};
